import { test, expect } from '@playwright/test';

test.describe('Image Scaling on Mobile Viewport', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/images');
  });

  test('should scale down images to fit screen width on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 862 });

    // Verify the first image is visible and scaled
    const firstImage = page.getByRole('img', { name: /image 1/i });
    await expect(firstImage).toBeVisible();

    // Verify the image width is less than the viewport width
    const imageWidth = await firstImage.evaluate((el) => el.style.width);
    expect(imageWidth).toBeLessThan('375px');

    // Verify the image height is scaled proportionally
    const imageHeight = await firstImage.evaluate((el) => el.style.height);
    expect(imageHeight).toBeLessThan('1000px');

    // Verify the image has the correct aspect ratio
    const aspectRatio = await firstImage.evaluate((el) => {
      const width = el.style.width;
      const height = el.style.height;
      return parseFloat(width) / parseFloat(height);
    });
    expect(aspectRatio).toBeCloseTo(1 / 1.5);

    // Verify the image is responsive by resizing the viewport
    await page.setViewportSize({ width: 320, height: 600 });
    const resizedImage = page.getByRole('img', { name: /image 1/i });
    await expect(resizedImage).toBeVisible();

    const newImageWidth = await resizedImage.evaluate((el) => el.style.width);
    expect(newImageWidth).toBeLessThan('320px');
  });

  test('should handle large images gracefully and maintain aspect ratio on mobile', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 860 });

    // Verify the second image is visible
    const secondImage = page.getByRole('img', { name: /image 2/i });
    await expect(secondImage).toBeVisible();

    // Verify the image is scaled down
    const imageWidth = await secondImage.evaluate((el) => el.style.width);
    expect(imageWidth).toBeLessThan('375px');

    // Verify the image height is scaled proportionally
    const imageHeight = await secondImage.evaluate((el) => el.style.height);
    expect(imageHeight).toBeLessThan('1000px');

    // Verify the image has the correct aspect ratio
    const aspectRatio = await secondImage.evaluate((el) => {
      const width = el.style.width;
      const height = el.style.height;
      return parseFloat(width) / parseFloat(height);
    });
    expect(aspectRatio).toBeCloseTo(1 / 2.5);

    // Verify the image is not distorted
    const imageBoundingBox = await secondImage.boundingBox();
    expect(imageBoundingBox).not.toBeNull();

    // Verify the image is not overflowing the viewport
    const viewportWidth = 375;
    const viewportHeight = 860;
    expect(imageBoundingBox.x + imageBoundingBox.width).toBeLessThan(viewportWidth);
    expect(imageBoundingBox.y + imageBoundingBox.height).toBeLessThan(viewportHeight);
  });
});
